-- 975: Plastic molding cycle-time calculators -- one real database calculator for each molding process.
--
-- GENERATED by scripts/generate-plastic-molding-calculators-migration.ts from
-- src/modules/bom-items/costing/plastic-molding/calculators/plastic-molding-calculators.json.
-- Do not edit by hand: change the spec and regenerate.
--
-- ROOT CAUSE
--
-- The molding cycle times (injection and structural foam: Menges cooling, fill, pack, mold motion;
-- compression and reaction injection: press motion plus cure) were held only in TypeScript, and the four
-- Plastic Molding rows of process_calculator_mappings carried a calculator name with calculator_id NULL,
-- so the cost dialogs could not open the calculator behind a molding line the way they do for heat
-- treatment, machining or die casting. The one injection calculator in the catalog ("Injection Molding
-- Cycle time Calculation") is an older hand-built one that no mapping uses and that models ejection and
-- slider time the engine does not.
--
-- This migration creates one global calculator per spec entry (inputs are the
-- values the cost engine seeds, each shown with its source in the calculation
-- trace; calculated fields are the formulas the engine evaluates, it holds
-- none) and links every Plastic Molding catalog operation it computes to its
-- calculator in process_calculator_mappings.
--
-- Requires migration 804 (calculators.retired_at).
-- Self-contained, idempotent, post-checked.

BEGIN;

-- Injection Molding - Cycle Time
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Injection Molding - Cycle Time$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Injection Molding - Cycle Time$q$, 'process', 'single', false, true, true, $q$Injection cycle time = (Fill + Pack + Cooling + Mold open/close) x Cycle Time Adjustment Factor (formula registry F-08, ASSUMED). Cooling is the Menges plate-cooling equation, t = s^2 / (pi^2 alpha) x ln((4/pi)(Tm - Tw)/(Te - Tw)), alpha = k / (rho cp) (F-04, ASSUMED: memory/ holds no cooling formula). Fill = shot melt volume / the press injection rate x the injectionTimeAdjustmentFactors for cavities and gates (F-05, VALIDATED). Pack = 35 % of cooling with a 2 s floor, the Menges gate-freeze rule (F-06, ASSUMED: the reference holds no hold time). Mold open/close = the press Euromap 6 dry cycle (F-07, VALIDATED). Not modelled, because the reference has no formula or press data: ejector travel, plasticizing, part and material handling, slides and lifters. Rounded as the engine does: cooling and pack to 0.1 s, fill and the total to 0.01 s.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$Injection cycle time = (Fill + Pack + Cooling + Mold open/close) x Cycle Time Adjustment Factor (formula registry F-08, ASSUMED). Cooling is the Menges plate-cooling equation, t = s^2 / (pi^2 alpha) x ln((4/pi)(Tm - Tw)/(Te - Tw)), alpha = k / (rho cp) (F-04, ASSUMED: memory/ holds no cooling formula). Fill = shot melt volume / the press injection rate x the injectionTimeAdjustmentFactors for cavities and gates (F-05, VALIDATED). Pack = 35 % of cooling with a 2 s floor, the Menges gate-freeze rule (F-06, ASSUMED: the reference holds no hold time). Mold open/close = the press Euromap 6 dry cycle (F-07, VALIDATED). Not modelled, because the reference has no formula or press data: ejector travel, plasticizing, part and material handling, slides and lifters. Rounded as the engine does: cooling and pack to 0.1 s, fill and the total to 0.01 s.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Nominal Wall Thickness$q$, $q$Nominal Wall Thickness (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Melt Temperature$q$, $q$Melt Temperature (°C)$q$, $q$number$q$, $q$°C$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Mold Temperature$q$, $q$Mold Temperature (°C)$q$, $q$number$q$, $q$°C$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Mold Temperature Increase$q$, $q$Mold Temperature Increase (°C)$q$, $q$number$q$, $q$°C$q$, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Ejection Temperature$q$, $q$Ejection Temperature (°C)$q$, $q$number$q$, $q$°C$q$, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Specific Heat of Melt$q$, $q$Specific Heat of Melt (J/g·K)$q$, $q$number$q$, $q$J/g·K$q$, NULL, NULL, NULL, NULL, 6, true),
    (v_id, $q$Thermal Conductivity of Melt$q$, $q$Thermal Conductivity of Melt (W/m·K)$q$, $q$number$q$, $q$W/m·K$q$, NULL, NULL, NULL, NULL, 7, true),
