    (v_id, $q$Fill Factor for Cavities$q$, $q$Fill Factor for Cavities$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 11, true),
    (v_id, $q$Fill Factor for Gates$q$, $q$Fill Factor for Gates$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 12, true),
    (v_id, $q$Press Dry Cycle Time$q$, $q$Press Dry Cycle Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 13, true),
    (v_id, $q$Cycle Time Adjustment Factor$q$, $q$Cycle Time Adjustment Factor$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 14, true),
    (v_id, $q$Mold Wall Temperature$q$, $q$Mold Wall Temperature (°C)$q$, $q$calculated$q$, $q$°C$q$, NULL, NULL, NULL, $q${Mold Temperature} + {Mold Temperature Increase}$q$, 15, false),
    (v_id, $q$Thermal Diffusivity$q$, $q$Thermal Diffusivity (mm²/s)$q$, $q$calculated$q$, $q$mm²/s$q$, NULL, NULL, NULL, $q${Thermal Conductivity of Melt} / ({Melt Density} * {Specific Heat of Melt} * 1000) * 1000000$q$, 16, false),
    (v_id, $q$Cooling Time$q$, $q$Cooling Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$floor({Nominal Wall Thickness} * {Nominal Wall Thickness} / (pi * pi * {Thermal Diffusivity}) * LN(4 / pi * ({Melt Temperature} - {Mold Wall Temperature}) / ({Ejection Temperature} - {Mold Wall Temperature})) * 10 + 0.5) / 10$q$, 17, false),
    (v_id, $q$Fill Time$q$, $q$Fill Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$floor({Shot Melt Volume} / {Press Injection Rate} * {Fill Factor for Cavities} * {Fill Factor for Gates} * 100 + 0.5) / 100$q$, 18, false),
    (v_id, $q$Pack to Cooling Ratio$q$, $q$Pack to Cooling Ratio$q$, $q$calculated$q$, NULL, NULL, NULL, NULL, $q$0.35$q$, 19, false),
