-- Compression Molding - Cycle Time
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Compression Molding - Cycle Time$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Compression Molding - Cycle Time$q$, 'process', 'single', false, true, true, $q$Compression cycle = press open/close time (the staged press_cycle_time_s: platen close + open motion) + the material's cure time. Not modelled, because the reference holds no formula: charging, preheat, flash trimming and part handling. The cycle is understated by those until validated formulas are supplied; a grade with no cure time on file contributes none (said in the trace).$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$Compression cycle = press open/close time (the staged press_cycle_time_s: platen close + open motion) + the material's cure time. Not modelled, because the reference holds no formula: charging, preheat, flash trimming and part handling. The cycle is understated by those until validated formulas are supplied; a grade with no cure time on file contributes none (said in the trace).$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Press Open/Close Time$q$, $q$Press Open/Close Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Material Cure Time$q$, $q$Material Cure Time (min)$q$, $q$number$q$, $q$min$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Cure Time$q$, $q$Cure Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Material Cure Time} * 60$q$, 3, false),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Press Open/Close Time} + {Cure Time}$q$, 4, false);

  UPDATE public.process_calculator_mappings
  SET calculator_id = v_id, calculator_name = $q$Compression Molding - Cycle Time$q$
  WHERE process_group = $q$Plastic Molding$q$ AND operation IN ($q$Compression Molding$q$);
END
$calc$;

