    (v_id, $q$Machine Dry Cycle Time$q$, $q$Machine Dry Cycle Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Material Cure Time$q$, $q$Material Cure Time (min)$q$, $q$number$q$, $q$min$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Cure Time$q$, $q$Cure Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Material Cure Time} * 60$q$, 3, false),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Machine Dry Cycle Time} + {Cure Time}$q$, 4, false);

  UPDATE public.process_calculator_mappings
  SET calculator_id = v_id, calculator_name = $q$Reaction Injection Molding - Cycle Time$q$
  WHERE process_group = $q$Plastic Molding$q$ AND operation IN ($q$Reaction Injection Molding$q$);
END
$calc$;

-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Injection Molding - Cycle Time$q$, 22, 1),
    ($q$Injection Molding - LSR Cycle Time$q$, 14, 0),
    ($q$Structural Foam Molding - Cycle Time$q$, 22, 1),
    ($q$Compression Molding - Cycle Time$q$, 4, 1),
    ($q$Reaction Injection Molding - Cycle Time$q$, 4, 1)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Plastic Molding$q$) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 975: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
